import Image from "next/image";
import { getTranslations } from "next-intl/server";
import { iconSrc } from "@/lib/icon";
import { getStack } from "@/lib/content";
import { ExperiencesList } from "@/components/About/ExperiencesList";
import { AboutProfilePicture } from "@/components/About/AboutProfilePicture";
import { Divider } from "@/components/primitives/Divider";
import { experiences } from "@/lib/site-config";
import { SpotlightCard } from "@/components/primitives/SpotlightCard";

type AboutSlots = {
  title?: string;
  subtitle?: string;
  profile_image?: string;
  intro?: string;
  stack_title?: string;
  stack_description?: string;
};

export async function AboutSection({ slots }: { slots: AboutSlots }) {
  const stack = getStack();
  const t = await getTranslations("global");
  return (
    <section className="mx-auto mt-4 flex w-full max-w-5xl flex-col p-7 text-[var(--font-primary)] sm:mt-20 xl:max-w-6xl">
      <h1 className="font-newsreader text-left text-4xl text-white-shadow">
        {slots.title}
      </h1>
      <h2 className="mt-5 text-left text-lg font-extralight text-muted sm:mt-6">
        {slots.subtitle}
      </h2>
      <Divider className="mb-8 mt-2" />
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-start sm:gap-8 lg:gap-12">
        <AboutProfilePicture pictureSrc={slots.profile_image} />
        <div className="flex max-w-xl flex-col gap-3 lg:max-w-2xl">
          <h3 className="text-lg">Introduction</h3>
          <div className="flex flex-col gap-4 whitespace-pre-wrap">{slots.intro}</div>
        </div>
      </div>
      <Divider className="my-8" />
      <ExperiencesList experiences={experiences} heading={t("experiences")} />
      <Divider className="my-8" />
      <div className="flex flex-col gap-3">
        <div className="mb-6 flex flex-col gap-2">
          <h3 className="font-newsreader text-3xl text-white-shadow">
            {slots.stack_title}
          </h3>
          <p>{slots.stack_description}</p>
        </div>
        <div className="flex flex-wrap justify-center gap-4">
          {stack.items.map((item) => (
            <SpotlightCard white key={item.name}>
              <a
                href={item.link}
                target="_blank"
                rel="noreferrer"
                aria-label={`${item.name} link`}
                className="flex gap-2 p-6"
              >
                <Image
                  src={iconSrc(item.icon)}
                  alt=""
                  width={36}
                  height={36}
                  className="size-9"
                />
              </a>
            </SpotlightCard>
          ))}
        </div>
      </div>
    </section>
  );
}
